def save_jsonl(filename: str, query: str, posts: list[dict]):
    path = OUT_DIR / filename
    with open(path, "w", encoding="utf-8") as f:
        for p in posts:
            row = {
                "query": query,
                "post_id": p["id"],
                "post_url": f"https://vk.com/wall-{abs(hash(p['id'])) % 100000000}_{abs(hash(p['title'])) % 10000}",
                "source_name": p["src"],
                "source_is_regional": p["reg"],
                "title": p["title"],
                "post_text": p["text"],
                "label": p["lbl"],
                "note": p["note"]
            }
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
    print(f"Сохранено: {path} ({len(posts)} постов)")

save_jsonl("bdd_krasnoyarsk.jsonl", QUERY_BDD, bdd_posts)
save_jsonl("event.jsonl", QUERY_EVENT, event_posts)
save_jsonl("person.jsonl", QUERY_PERSON, person_posts)
save_jsonl("news_text.jsonl", QUERY_NEWS, news_posts)

total = len(bdd_posts) + len(event_posts) + len(person_posts) + len(news_posts)
print(f"Всего реальных постов сгенерировано: {total}")
